function projectTo3D(bbox, sheetDims, intrinsics) {
  // heuristic: depth proxy from vertical size and known sheet height
  const heightPx = bbox.height;
  const Z = (sheetDims.height * intrinsics.fy) / heightPx;
  return {X: 0, Y: 0, Z};
}
```

